   "code_before": "# ledger_etl/jobs/brokerage/cash_sweep.py  (legacy monolith)\nfrom ledger_etl.common.utils import *\nfrom ledger_etl.common import db, config\nfrom ledger_etl.jobs.brokerage.order_fills_ingest import get_rows\n\nCONFIG = config.load_global()\n\ndef compute(as_of=None):\n    as_of = as_of or today_str()\n    rows = get_rows(as_of)\n    method = CONFIG.get(\"sweep_method\", \"FIFO\")\n    results = []\n    for acct, lots in group_by(rows, \"account_id\").items():\n        lots = sorted(lots, key=lambda l: l[\"acquired\"])\n        if method == \"LIFO\":\n            lots.reverse()\n        total = 0.0\n        for l in lots:\n            total = total + round(l[\"qty\"] * l[\"unit_cost\"], 2)\n        results.append({\"account_id\": acct, \"value\": total, \"method\": method})\n    db.write(\"brk_cash_sweep\", results, mode=\"overwrite\")\n    return results\n",
   "code_after": "# submodules/brokerage_cash_sweep/src/brokerage_cash_sweep/engine.py\nfrom dataclasses import dataclass\nfrom datetime import date\nfrom decimal import ROUND_HALF_EVEN, Decimal\nfrom enum import Enum\nfrom itertools import groupby\n\nfrom ledger_contracts.brokerage import OrderFillSource\nfrom ledger_platform.io import TableWriter\nfrom .schema import SweepResult\n\nCENT = Decimal(\"0.01\")\n\nclass LotMethod(str, Enum):\n    FIFO = \"FIFO\"\n    LIFO = \"LIFO\"\n\n@dataclass(frozen=True)\nclass SweepEngine:\n    upstream: OrderFillSource\n    sink: TableWriter\n    method: LotMethod = LotMethod.FIFO\n\n    def compute(self, as_of: date) -> list[SweepResult]:\n        rows = sorted(self.upstream.for_date(as_of), key=lambda l: (l.account_id, l.acquired))\n        results = []\n        for acct, lots in groupby(rows, key=lambda l: l.account_id):\n            ordered = list(lots)\n            if self.method is LotMethod.LIFO:\n                ordered.reverse()\n            total = sum(((l.qty * l.unit_cost).quantize(CENT, ROUND_HALF_EVEN)\n                         for l in ordered), Decimal(0))\n            results.append(SweepResult(account_id=acct, value=total, method=self.method))\n        self.sink.overwrite(\"brk_cash_sweep\", results, partition=as_of)\n        return results\n",
