   "code_before": "# ledger_etl/jobs/wealth/advisor_book_rollup.py  (legacy monolith)\nfrom ledger_etl.common.utils import *\nfrom ledger_etl.common import db\nfrom ledger_etl.jobs.wealth.household_rollup import TABLE as UPSTREAM_TABLE\nimport ledger_etl.jobs.marketdata.eod_prices as px\n\ndef run(as_of=None):\n    as_of = as_of or today_str()\n    rows = db.query(\"SELECT * FROM %s WHERE as_of='%s'\" % (UPSTREAM_TABLE, as_of))\n    prices = px.PRICE_CACHE      # populated as a side effect of an earlier job\n    agg = {}\n    for r in rows:\n        key = (r[\"account_id\"], r[\"advisor_id\"])\n        p = prices.get(r[\"security_id\"], 0)      # missing price -> silently 0\n        a = agg.setdefault(key, {\"qty\": 0, \"mv\": 0.0})\n        a[\"qty\"] += r[\"quantity\"]\n        a[\"mv\"] += r[\"quantity\"] * p\n    out = [dict(account_id=k[0], advisor_id=k[1], **v) for k, v in agg.items()]\n    db.write(\"wlt_advisor_book\", out, mode=\"overwrite\")\n    return out\n",
   "code_after": "# submodules/wealth_advisor_book_rollup/src/wealth_advisor_book_rollup/rollup.py\nfrom collections import defaultdict\nfrom dataclasses import dataclass\nfrom datetime import date\nfrom decimal import Decimal\n\nfrom ledger_contracts.wealth import HouseholdSource\nfrom ledger_contracts.marketdata import PriceSource\nfrom ledger_platform.io import TableWriter\nfrom .schema import AdvisorBookRow, MissingPrice\n\n@dataclass(frozen=True)\nclass AdvisorBookRollup:\n    upstream: HouseholdSource\n    prices: PriceSource\n    sink: TableWriter\n\n    def run(self, as_of: date) -> list[AdvisorBookRow]:\n        qty: dict[tuple, Decimal] = defaultdict(Decimal)\n        mv: dict[tuple, Decimal] = defaultdict(Decimal)\n        price_book = self.prices.close_for(as_of)\n        for r in self.upstream.for_date(as_of):\n            if r.security_id not in price_book:\n                raise MissingPrice(r.security_id, as_of)\n            key = (r.account_id, r.advisor_id)\n            qty[key] += r.quantity\n            mv[key] += r.quantity * price_book[r.security_id]\n        out = [AdvisorBookRow(account_id=a, advisor_id=g, qty=qty[(a, g)], mv=mv[(a, g)])\n               for (a, g) in sorted(qty)]\n        self.sink.overwrite(\"wlt_advisor_book\", out, partition=as_of)\n        return out\n",
