   "code_after": "# submodules/statements_consolidated_annual/src/statements_consolidated_annual/export.py\nfrom dataclasses import dataclass\nfrom datetime import date\n\nfrom ledger_contracts.statements import BrokerageStmtSource\nfrom ledger_platform.io import ExportSink, ExportLog\nfrom ledger_platform.security import TokenVault\nfrom ledger_platform.time import period_of\nfrom .schema import AnnualStmtLine\n\n@dataclass(frozen=True)\nclass AnnualStmtExport:\n    upstream: BrokerageStmtSource\n    vault: TokenVault\n    sink: ExportSink\n    audit: ExportLog\n\n    def run(self, as_of: date) -> int:\n        lines = [\n            AnnualStmtLine(account_id=r.account_id,\n                          tax_id_token=self.vault.tokenize(r.tax_id),\n                          total=r.total)\n            for r in self.upstream.for_period(period_of(as_of))\n        ]\n        with self.sink.atomic(\"annual_stmt\", as_of) as out:   # temp file + rename\n            out.write_psv(lines)\n        self.audit.record(\"statements.consolidated_annual\", as_of, count=len(lines))\n        return len(lines)\n",
